const { page_id, page_access_token, message, image_urls, link, published } = $input.first().json;

const errors = [];
if (!page_id) errors.push('page_id is required');
if (!page_access_token) errors.push('page_access_token is required');
if (!message && !image_urls?.length && !link) errors.push('At least one of message, image_urls, or link is required');

if (errors.length > 0) {
  throw new Error('Validation failed: ' + errors.join('; '));
}

return {
  page_id,
  page_access_token,
  message: message || '',
  image_urls: Array.isArray(image_urls) ? image_urls : [],
  link: link || '',
  published: published !== false,
  schedule_time: $input.first().json.schedule_time || null
};

const items = $input.all();
const results = [];

for (const item of items) {
  const { page_id, page_access_token, message, image_urls, link, published } = item.json;

  // Upload each image as unpublished media
  const mediaIds = [];
  for (const url of image_urls) {
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://graph.facebook.com/v25.0/${page_id}/photos`,
      qs: {
        url: url,
        published: false,
        access_token: page_access_token
      }
    });
    mediaIds.push({ media_fbid: response.id });
  }

  // If only one image, use /photos endpoint with message
  if (mediaIds.length === 1 && message) {
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://graph.facebook.com/v25.0/${page_id}/photos`,
      qs: {
        url: image_urls[0],
        message: message,
        access_token: page_access_token
      }
    });
    results.push({ post_id: response.id, post_type: 'photo' });
    continue;
  }

  // For text-only or multiple images, use /feed endpoint
  const feedParams = {
    message: message,
    access_token: page_access_token
  };

  if (mediaIds.length > 0) {
    feedParams.attached_media = JSON.stringify(mediaIds);
  }

  if (link) {
    feedParams.link = link;
  }

  if (item.json.schedule_time) {
    feedParams.scheduled_publish_time = Math.floor(new Date(item.json.schedule_time).getTime() / 1000);
  }

  if (published === false && !item.json.schedule_time) {
    feedParams.published = false;
  }

  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://graph.facebook.com/v25.0/${page_id}/feed`,
    qs: feedParams
  });

  results.push({
    post_id: response.id,
    post_type: mediaIds.length > 1 ? 'multi_photo' : link ? 'link' : 'text',
    image_count: mediaIds.length
  });
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const { page_id, page_access_token, message, link, published } = item.json;

  const params = {
    message: message,
    access_token: page_access_token
  };

  if (link) {
    params.link = link;
  }

  if (item.json.schedule_time) {
    params.scheduled_publish_time = Math.floor(new Date(item.json.schedule_time).getTime() / 1000);
  }

  if (published === false && !item.json.schedule_time) {
    params.published = false;
  }

  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://graph.facebook.com/v25.0/${page_id}/feed`,
    qs: params
  });

  results.push({
    post_id: response.id,
    post_type: link ? 'link' : 'text',
    image_count: 0
  });
}

return results;

const items = $input.all();

return items.map(item => ({
  success: true,
  post_id: item.json.post_id,
  post_type: item.json.post_type,
  image_count: item.json.image_count || 0,
  timestamp: new Date().toISOString(),
  status: 'published',
  page_url: `https://facebook.com/${item.json.post_id}`
}));

const items = $input.all();
return items.map(item => ({
  level: 'error',
  input: item.json,
  error: item.json.error || 'Unknown error',
  timestamp: new Date().toISOString()
}));
